-- Money in and money out: money into or out of a cash or bank account that no other form records.
-- track: C
--
-- The CREATE TABLE / index statements are generated by drizzle-kit from
-- src/modules/money-in-out/schema.ts. The sections marked "hand-written" are not managed by
-- Drizzle. Reverse with the file of the same name in drizzle/down.
--
-- Why (batch A, 2026-11-27): a customer's receipt, a supplier payment, an expense, a salary and a
-- transfer each have a form. The owner's capital put in, a loan received or repaid, drawings and
-- other income had none, short of a manual journal. Each is now one document with its own number:
--
--   Money in  (MI-):  debit  the cash or bank account   the amount
--                     credit the other account          the amount
--   Money out (MO-):  debit  the other account          the amount
--                     credit the cash or bank account   the amount
--
-- The other account is any account of the company that takes postings, is in use and is not a
-- control account (receivables, payables, stock, tax, cash and bank, retained earnings and the
-- rest are kept by their own documents). Money out never goes to an expense account: an expense
-- has its own form, which withholds tax where the law says so. Written, with its journal and its
-- audit rows, by one function of the database's own; one entered by mistake is cancelled with a
-- reversal and a reason, never changed. Kept by the owner and an accountant who work in every
-- branch (the accounts belong to the whole company, as transfers do), read by the auditor too.
--
-- What it uses of this track's Step 34 (drizzle/0038_cash_bank.sql), calling it as it stands:
-- app.cash_bank_may_write (role, read committed, no future date, open period),
-- app.cash_bank_account (one of the company's cash or bank accounts in use), app.cash_bank_reopenable
-- and app.cash_bank_reverse. It changes no function, policy or trigger, and no row of any company.
--
-- Database error codes (the money range, SE300 to SE399), with the meanings Step 34 gave them:
--   SE331  not one of the company's cash or bank accounts in use
--   SE332  an amount, a reason or a transaction that will not do
--   SE333  a date that has not come yet, or before the document's own
--   SE334  no such entry in this company
--   SE335  already cancelled
--   SE341  an archived account a cancellation would post to: restore it first
--   SE342  sent again with the same key but other figures: the first was recorded
-- and new here:
--   SE381  the other account will not do: not the company's, a heading, archived, a control
--          account, or (money out) an expense account
--   SE382  from or to whom, in words, is missing or too long

-- ── generated by drizzle-kit ────────────────────────────────────────────────────────────────────

CREATE TABLE "money_in_out" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"direction" text NOT NULL,
	"number" text NOT NULL,
	"entry_date" date NOT NULL,
	"money_account_id" uuid NOT NULL,
	"other_account_id" uuid NOT NULL,
	"amount" numeric(20, 4) NOT NULL,
	"party" text NOT NULL,
	"reference" text,
	"memo" text,
	"status" text NOT NULL,
	"journal_id" uuid NOT NULL,
	"reversal_journal_id" uuid,
	"cancelled_at" timestamp with time zone,
	"cancelled_by" uuid,
	"cancel_reason" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" uuid NOT NULL,
	CONSTRAINT "money_in_out_tenant_id_id_key" UNIQUE("tenant_id","id"),
	CONSTRAINT "money_in_out_number_key" UNIQUE("tenant_id","number"),
	CONSTRAINT "money_in_out_direction_known" CHECK ("money_in_out"."direction" in ('in', 'out')),
	CONSTRAINT "money_in_out_accounts_differ" CHECK ("money_in_out"."money_account_id" <> "money_in_out"."other_account_id"),
	CONSTRAINT "money_in_out_amount_sane" CHECK ("money_in_out"."amount" > 0 and "money_in_out"."amount" < 1e14),
	CONSTRAINT "money_in_out_status_known" CHECK ("money_in_out"."status" in ('posted', 'cancelled')),
	CONSTRAINT "money_in_out_number_format" CHECK ("money_in_out"."number" ~ '^M[IO]-[0-9]{4}-[0-9]{5,}$' and substr("money_in_out"."number", 2, 1) = (case "money_in_out"."direction" when 'in' then 'I' else 'O' end)),
	CONSTRAINT "money_in_out_cancelled_is_whole" CHECK (("money_in_out"."status" = 'cancelled') = ("money_in_out"."reversal_journal_id" is not null) and ("money_in_out"."status" = 'cancelled') = ("money_in_out"."cancelled_at" is not null)
        and ("money_in_out"."status" = 'cancelled') = ("money_in_out"."cancelled_by" is not null) and ("money_in_out"."status" = 'cancelled') = ("money_in_out"."cancel_reason" is not null)),
	CONSTRAINT "money_in_out_party_length" CHECK (char_length(btrim("money_in_out"."party")) between 2 and 120 and "money_in_out"."party" = btrim("money_in_out"."party")),
	CONSTRAINT "money_in_out_text_length" CHECK (char_length(btrim("money_in_out"."reference")) between 1 and 60 and char_length(btrim("money_in_out"."memo")) between 1 and 300)
);
