-- ── hand-written: recording and cancelling ──────────────────────────────────────────────────────
-- Not for the app to call. The other side of money in or out: one of the company's accounts that
-- takes postings, in use, not a control account, not a cash or bank account (that is a transfer),
-- and for money out not an expense (that is an expense). Held until the transaction ends, so it
-- cannot be archived while something is posted to it. Anything else is refused (SE381).
CREATE FUNCTION app.money_in_out_other_account(p_tenant uuid, p_account uuid, p_direction text) RETURNS public.accounts
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_account public.accounts%ROWTYPE;
BEGIN
  SELECT a.* INTO v_account FROM public.accounts a WHERE a.tenant_id = p_tenant AND a.id = p_account FOR SHARE;
  IF NOT FOUND OR v_account.is_group OR v_account.archived_at IS NOT NULL OR v_account.is_control OR v_account.control_type IS NOT NULL
     OR (p_direction = 'out' AND v_account.type = 'expense') THEN
    RAISE EXCEPTION 'choose an account in use that is not a control account%', CASE WHEN p_direction = 'out' THEN ' or an expense' ELSE '' END USING ERRCODE = 'SE381';
  END IF;
  RETURN v_account;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.money_in_out_other_account(uuid, uuid, text) FROM PUBLIC;
--> statement-breakpoint
-- Money into (p_direction 'in') or out of ('out') one of the company's cash or bank accounts, from
-- or to one other account. Returns its number. Sent again with the same key, the first is the one
-- recorded, if it is the same entry.
CREATE FUNCTION app.record_money_in_out(p_key uuid, p_direction text, p_date date, p_money_account uuid, p_other_account uuid, p_amount numeric,
                                        p_party text, p_reference text, p_memo text) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_money public.accounts%ROWTYPE;
  v_other public.accounts%ROWTYPE;
  v_id uuid := coalesce(p_key, gen_random_uuid());
  v_party text := regexp_replace(btrim(coalesce(p_party, '')), '\s+', ' ', 'g');
  v_number text;
  v_journal uuid;
  v_word text;
  v_sent public.money_in_out%ROWTYPE;
BEGIN
  PERFORM app.cash_bank_may_write(p_date);
  IF app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'money in and out of the company''s accounts is recorded by someone who works in every branch' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_direction IS NULL OR p_direction NOT IN ('in', 'out') THEN
    RAISE EXCEPTION 'money comes in or goes out' USING ERRCODE = 'SE332';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('money-in-out:' || v_id::text, 0));
  SELECT m.* INTO v_sent FROM public.money_in_out m WHERE m.tenant_id = v_tenant AND m.id = v_id;
  IF FOUND THEN
    IF v_sent.direction IS DISTINCT FROM p_direction OR v_sent.money_account_id IS DISTINCT FROM p_money_account OR v_sent.other_account_id IS DISTINCT FROM p_other_account
       OR v_sent.entry_date IS DISTINCT FROM p_date OR v_sent.amount IS DISTINCT FROM p_amount THEN
      RAISE EXCEPTION 'already recorded as % with other figures', v_sent.number USING ERRCODE = 'SE342';
    END IF;
    RETURN v_sent.number;
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount >= 1e14 OR round(p_amount, 2) <> p_amount THEN
    RAISE EXCEPTION 'an amount in rupees and paisa, above nothing' USING ERRCODE = 'SE332';
  END IF;
  IF char_length(v_party) NOT BETWEEN 2 AND 120 THEN
    RAISE EXCEPTION 'say from or to whom, in words' USING ERRCODE = 'SE382';
  END IF;
  IF char_length(btrim(p_reference)) > 60 OR char_length(btrim(p_memo)) > 300 THEN
    RAISE EXCEPTION 'a reference of at most 60 characters and a note of at most 300' USING ERRCODE = 'SE332';
  END IF;
  IF p_money_account IS NULL THEN
    RAISE EXCEPTION 'choose one of the company''s cash or bank accounts that is in use' USING ERRCODE = 'SE331';
  END IF;
  v_money := app.cash_bank_account(v_tenant, p_money_account);
  v_other := app.money_in_out_other_account(v_tenant, p_other_account, p_direction);
  v_number := app.next_document_number(CASE p_direction WHEN 'in' THEN 'MI' ELSE 'MO' END, p_date);
  v_word := CASE p_direction WHEN 'in' THEN 'Money in from ' ELSE 'Money out to ' END;
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, created_by)
    VALUES (v_tenant, p_date, 'money_in_out', v_id, v_number, left(v_word || v_party, 500), v_user)
    RETURNING id INTO v_journal;
  IF p_direction = 'in' THEN
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, 1, v_money.id, p_amount, 0, left(v_word || v_party, 500)),
             (v_tenant, v_journal, 2, v_other.id, 0, p_amount, left(v_word || v_party, 500));
  ELSE
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, 1, v_other.id, p_amount, 0, left(v_word || v_party, 500)),
             (v_tenant, v_journal, 2, v_money.id, 0, p_amount, left(v_word || v_party, 500));
  END IF;
  INSERT INTO public.money_in_out (id, tenant_id, direction, number, entry_date, money_account_id, other_account_id, amount, party, reference, memo, status, journal_id, created_by)
    VALUES (v_id, v_tenant, p_direction, v_number, p_date, v_money.id, v_other.id, p_amount, v_party, nullif(btrim(p_reference), ''), nullif(btrim(p_memo), ''), 'posted', v_journal, v_user);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, app.tenant_role(), 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', p_date, 'source', 'money_in_out', 'sourceId', v_id, 'number', v_number, 'lines', 2, 'total', p_amount::text)),
           (v_tenant, v_user, app.tenant_role(), 'money_in_out.record', 'money_in_out', v_id,
      jsonb_build_object('number', v_number, 'direction', p_direction, 'date', p_date, 'account', v_money.name, 'other', v_other.name, 'party', v_party, 'amount', p_amount::text));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.record_money_in_out(uuid, text, date, uuid, uuid, numeric, text, text, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.record_money_in_out(uuid, text, date, uuid, uuid, numeric, text, text, text) TO app_runtime;
--> statement-breakpoint
-- An entry made by mistake is taken back with a reversal, on or after its own day, with a reason.
CREATE FUNCTION app.cancel_money_in_out(p_id uuid, p_date date, p_reason text) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_doc public.money_in_out%ROWTYPE;
  v_reversal uuid;
BEGIN
  PERFORM app.cash_bank_may_write(p_date);
  IF app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'money in and out of the company''s accounts is recorded by someone who works in every branch' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT m.* INTO v_doc FROM public.money_in_out m WHERE m.tenant_id = v_tenant AND m.id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such entry in this company' USING ERRCODE = 'SE334';
  END IF;
  IF v_doc.status <> 'posted' THEN
    RAISE EXCEPTION 'this entry has already been cancelled' USING ERRCODE = 'SE335';
  END IF;
  IF p_date < v_doc.entry_date THEN
    RAISE EXCEPTION 'an entry is cancelled on or after its own day' USING ERRCODE = 'SE333';
  END IF;
  IF p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 3 AND 300 THEN
    RAISE EXCEPTION 'say why the entry is cancelled' USING ERRCODE = 'SE332';
  END IF;
  PERFORM app.cash_bank_reopenable(v_tenant, v_doc.money_account_id);
  PERFORM app.cash_bank_reopenable(v_tenant, v_doc.other_account_id);
  v_reversal := app.cash_bank_reverse(v_doc.journal_id, p_date, 'Cancelled: ' || v_doc.number || ' (' || btrim(p_reason) || ')');
  UPDATE public.money_in_out m SET status = 'cancelled', reversal_journal_id = v_reversal, cancelled_at = now(), cancelled_by = app.current_user_id(), cancel_reason = btrim(p_reason)
    WHERE m.tenant_id = v_tenant AND m.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_tenant, app.current_user_id(), app.tenant_role(), 'money_in_out.cancel', 'money_in_out', v_doc.id,
      jsonb_build_object('status', 'posted'), jsonb_build_object('status', 'cancelled', 'number', v_doc.number, 'date', p_date, 'reason', btrim(p_reason)));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.cancel_money_in_out(uuid, date, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.cancel_money_in_out(uuid, date, text) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: the shared lists (drizzle/0019_journal_documents.sql) ─────────────────────────
-- Each journal stands with its entry, and each reversal with one cancelled.
CREATE FUNCTION app.journal_backed_money_in_out(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.money_in_out m
      WHERE m.tenant_id = p_journal.tenant_id AND m.id = p_journal.source_id AND m.journal_id = p_journal.id
        AND m.number = p_journal.document_number AND m.entry_date = p_journal.journal_date)
  $$;
--> statement-breakpoint
CREATE FUNCTION app.reversal_backed_money_in_out(p_reversal public.journals, p_original public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.money_in_out m
      WHERE m.tenant_id = p_original.tenant_id AND m.journal_id = p_original.id AND m.reversal_journal_id = p_reversal.id AND m.status = 'cancelled')
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.journal_backed_money_in_out(public.journals), app.reversal_backed_money_in_out(public.journals, public.journals) FROM PUBLIC;
--> statement-breakpoint
-- Money in takes a number MI-2627-00001, money out MO-2627-00001.
CREATE FUNCTION app.document_type_mi() RETURNS text
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT 'money in'::text $$;
--> statement-breakpoint
CREATE FUNCTION app.document_type_mo() RETURNS text
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT 'money out'::text $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.document_type_mi(), app.document_type_mo() FROM PUBLIC;
--> statement-breakpoint
-- The audit rows only the functions above write: the app's role cannot write a look-alike.
CREATE FUNCTION app.audit_reserved_money_in_out(p_action text) RETURNS boolean
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT p_action IN ('money_in_out.record', 'money_in_out.cancel') $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.audit_reserved_money_in_out(text) FROM PUBLIC;
